package com.aetherforge.service;
import com.aetherforge.repo.UserRepository;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;import jakarta.annotation.PostConstruct;
@Component public class SeedUserInitializer {private final JdbcTemplate db;private final PasswordEncoder enc;public SeedUserInitializer(JdbcTemplate db,PasswordEncoder enc,UserRepository u){this.db=db;this.enc=enc;}@PostConstruct public void seed(){if(db.queryForObject("select count(*) from app_user",Long.class)==0){String sql="insert into app_user(email,full_name,password_hash,role) values(?,?,?,?)";db.update(sql,"admin@aetherforge.ai","Aether Admin",enc.encode("Admin@12345"),"ADMIN");db.update(sql,"engineer@aetherforge.ai","Maya Engineer",enc.encode("Engineer@12345"),"ENGINEER");db.update(sql,"operator@aetherforge.ai","Ravi Operator",enc.encode("Operator@12345"),"OPERATOR");db.update(sql,"viewer@aetherforge.ai","Nila Viewer",enc.encode("Viewer@12345"),"VIEWER");}}}
